tasks.powerShellScript:
$pathDocs = 'D:\Donnees_Marc'
$pathPics = 'E:\Archives_Photos'
if (!(Test-Path $pathDocs)) { New-Item -ItemType Directory -Path $pathDocs -Force }
if (!(Test-Path $pathPics)) { New-Item -ItemType Directory -Path $pathPics -Force }
Set-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders' -Name 'Personal' -Value $pathDocs
Set-ItemProperty -Path 'HKCU:\Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders' -Name 'My Pictures' -Value $pathPics
